INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62420766', 62420766, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM32 KANTOR IMIGRASI KELAS II TPI TAREMPA', 'Pengadaan Tenaga Alih Daya Anak Buah Kapal pada Kantor Imigrasi Kelas II TPI Tarempa - Kepulauan Riau Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Kepulauan Anambas (Kab.)', 150514000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '26 OB', 'Pengadaan tenaga alih daya (outsourcing) Anak Buah Kapal pada Kapal Patroli Imigrasi meliputi : 1) Menjalankan Perintah: Melaksanakan tugas sesuai perintah Nahkoda, menjalankan SOP dari Perusahaan serta Perintah dari Pejabat yang ditunjuk dan berwenang pada Kantor Imigrasi Kelas II TPI Tarempa. 2) Jaga dan Patroli: Melakukan dinas jaga dan pengawasan pada Kapal Patroli Imigrasi. 3) Pemeliharaan: Menjaga kebersihan dan kondisi rutin kapal, termasuk dek, mesin, dan akomodasi. 4) Keselamatan: Memastikan semua pekerjaan dilakukan aman dan membantu mencegah kecelakaan', 'A. Navigasi: Melaksanakan tugas jaga baik saat kapal sedang berlayar atau saat kapal sedang tambat serta memastikan tidak ada halangan di jalur pelayaran pada saat kapal berlayar. B. Pemeliharaan: Melakukan pembersihan baik di dalam kapal maupun di luar kapal, mengecat, dan memperbaiki bagian dek serta interior kapal . C. Keselamatan: Merawat dan memastikan alat keselamatan (sekoci, baju pelampung, alat pemadam api) siap pakai dan siap digunakan. D. Keamanan: Memastikan peralatan dan perlengkapan yang melekat dan menjadi satu kesatuan dengan Kapal Patroli Imigrasi tidak hilang. E. Operasional: Mengamankan tali-temali kapal, membantu saat sandar/labuh, menyiapkan dan menyajikan makanan untuk awak kapal dan penumpang, menjaga kebersihan dapur, ruang makan, dan akomodasi, mengelola persediaan bahan makanan dan kebutuhan dapur. F. Pelaporan dan Dokumentasi: Mencatat dan membuat laporan harian tentang pelaksanaan kegiatan selama bertugas, melaksanakan tugas dan atau melakukan penjagaan di Kapal', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 481805);
