INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62421318', 62421318, 'analyze_legacy', 'Kota Bekasi', 'kabkota', 'Rumah Sakit Umum Daerah', 'Pengelola Limbah B3 Medis', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kota)', 1800000000, 'December 2025', 'BLUD', 1, 1, '1 tahun', 'Uraian pekerjaan limbah B3 rumah sakit mencakup seluruh siklus pengelolaan mulai dari pemilahan, pewadahan, pengangkutan, penyimpanan sementara, pengolahan (autoclave, insinerasi, dll.), hingga pembuangan akhir (landfill/penimbunan), dengan tugas spesifik petugas seperti menimbang, memilah, membersihkan, mengangkut, membuat laporan, serta memastikan K3 dan kepatuhan regulasi untuk mencegah risiko kesehatan dan lingkungan.', '"Kriteria limbah B3 (Bahan Berbahaya dan Beracun) adalah limbah yang memiliki sifat mudah meledak, mudah terbakar, reaktif, korosif, beracun (toksik), infeksius, atau dapat merusak kesehatan dan lingkungan, termasuk sifat seperti karsinogenik, mutagenik, teratogenik, atau iritasi, yang ditetapkan melalui uji laboratorium seperti LD-50 atau TCLP. Limbah ini berbahaya karena konsentrasi, jumlah, atau sifatnya yang spesifik dapat menimbulkan bahaya serius jika tidak dikelola dengan benar. * Mudah Meledak (Explosiveness): Sangat tidak stabil, bisa meledak karena suhu, tekanan, atau kejutan. * Mudah Terbakar (Flammability): Mudah menyala, bahkan bisa terbakar dalam waktu lama, seperti bensin atau pelarut organik. * Reaktif (Reactivity): Sangat tidak stabil, dapat bereaksi dengan bahan lain (air, udara) menghasilkan gas beracun atau ledakan. * Korosif (Corrosiveness): Dapat merusak jaringan hidup atau logam, memiliki pH ekstrem (asam atau basa kuat). * Beracun (Toxicity): Mengandung zat kimia yang berbahaya bagi kesehatan atau lingkungan, seperti merkuri atau pestisida. * Infeksius (Infectiousness): Mengandung mikroorganisme patogen yang menyebabkan penyakit, contohnya limbah medis (jarum suntik bekas). * Iritasi/Narkotika/Psikotropika: Menyebabkan iritasi, pusing, atau efek berbahaya lainnya. * Karsinogenik, Mutagenik, Teratogenik (KMT): Menyebabkan kanker, mutasi genetik, atau cacat lahir. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 481907);
