INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62420760', 62420760, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM32 KANTOR IMIGRASI KELAS II TPI TAREMPA', 'Pengadaan Tenaga Alih Daya Nahkoda Kapal Patroli Imigrasi pada Kantor Imigrasi Kelas II TPI Tarempa - Kepulauan Riau Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Kepulauan Anambas (Kab.)', 84032000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '13 OB', 'Pengadaan tenaga alih daya (outsourcing) Nahkoda Kapal Patroli Imigrasi mencakup meliputi : 1) Keselamatan dan Keamanan: Bertanggung jawab penuh atas keselamatan seluruh awak kapal, penumpang, muatan, dan kapal itu sendiri selama pelayaran. 2) Operasional Kapal: Memimpin operasional harian kapal secara efisien dan aman, termasuk navigasi, pengelolaan rute, dan pemantauan kondisi kapal (dek dan mesin). 3) Kepatuhan Hukum dan Regulasi: Memastikan kapal beroperasi sesuai dengan hukum maritim nasional (seperti Undang-Undang Nomor 17 Tahun 2008 tentang Pelayaran) dan regulasi internasional yang berlaku. 4) Manajemen Kru: Memberikan arahan, bimbingan, dan pembinaan kepada seluruh kru, serta mengawasi jadwal dan kinerja mereka.', 'A. Navigasi dan Perencanaan Pelayaran: Merencanakan dan menjalankan navigasi kapal yang aman, termasuk menyesuaikan rute berdasarkan kondisi cuaca dan laut. B. Manajemen Kargo/Penumpang: Mengawasi proses pemuatan, pembongkaran, dan pengamanan muatan atau penumpang untuk memastikan keselamatan dan mencegah kerusakan. C. Administrasi dan Dokumentasi: Memelihara catatan dan logbook terperinci mengenai aktivitas harian, posisi kapal, kondisi cuaca, dan status kargo/personel, serta memastikan sertifikat kapal dan dokumenasinya lengkap dan valid. D. Koordinasi Eksternal: Berkoordinasi dengan otoritas pelabuhan, Syahbandar, distrik navigasi, dan pihak terkait lainnya di pelabuhan singgah. E. Penanganan Darurat: Siap menghadapi situasi darurat (kebakaran, kebocoran, medis) dan mengambil keputusan penting untuk menyelamatkan nyawa dan properti. F. Pemeliharaan: Mengawasi inspeksi dan perbaikan kapal secara berkala untuk memastikan kelaikan laut kapal', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 483544);
