INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65319809', 65319809, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KABUPATEN WONOGIRI', 'Pembelian ATK, MMT, Konsumsi dalam rangka Pelaksanaan Kegiatan Teknis Penyelenggaraan Pemilu dan Pilkada', 'Barang', 'Pengadaan Langsung', 'Jawa Tengah, Wonogiri (Kab.)', 2103000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Pkt, @ 2103000 )', 'Pembelian ATK, MMT, Konsumsi dalam rangka Pelaksanaan Kegiatan Teknis Penyelenggaraan Pemilu dan Pilkada ( 1, Pkt, @ 2103000 );', '1. Alat Tulis Kantor (ATK) ATK yang disediakan merupakan perlengkapan administrasi perkantoran untuk mendukung pelaksanaan kegiatan, dengan spesifikasi umum dapat diuraiakan sebagai berikut: Kertas HVS Ukuran A4 dan/atau F4, berat minimal 70 gram, warna putih, permukaan rata, tidak mudah tembus tinta, dan layak digunakan untuk pencetakan dokumen kegiatan. Pulpen Tinta warna hitam dan/atau biru, sistem tinta tidak mudah bocor, hasil tulisan jelas, dan nyaman digunakan. Pensil Jenis kayu dengan tingkat kekerasan standar (HB atau setara), tidak mudah patah, dan hasil tulisan jelas. Spidol Spidol papan tulis atau spidol permanen sesuai kebutuhan, warna hitam dan/atau warna lainnya, tinta jelas dan tidak mudah pudar. Map / Stopmap Bahan kertas atau plastik, ukuran A4/F4, kondisi baru, dan layak digunakan untuk pengarsipan dokumen kegiatan. Buku Catatan / Notes Ukuran standar, kertas tidak mudah sobek, dan dapat digunakan untuk pencatatan selama kegiatan. Perlengkapan ATK lainnya Perlengkapan pendukung administrasi kegiatan lainnya sesuai kebutuhan, seperti penghapus, penggaris, penjepit kertas, dan perlengkapan sejenis. Seluruh ATK harus dalam kondisi baru, tidak cacat, dan sesuai standar kualitas perkantoran. 2. Media Publikasi (MMT/Banner) Media publikasi berupa MMT atau banner kegiatan dengan spesifikasi sebagai berikut: Bahan cetak flexi atau bahan sejenis yang layak digunakan untuk kegiatan. Ukuran menyesuaikan kebutuhan kegiatan. Hasil cetak jelas, tidak buram, dan sesuai desain serta konten kegiatan. Dilengkapi dengan penyangga atau tali pengikat sesuai kebutuhan pemasangan. 3. Konsumsi Kegiatan Konsumsi kegiatan disediakan untuk peserta dan pihak terkait dengan spesifikasi sebagai berikut: Makanan dan/atau minuman sesuai waktu pelaksanaan kegiatan (snack dan/atau makan). Makanan dan minuman layak konsumsi, higienis, dan disajikan dalam kondisi baik. Disediakan tepat waktu sesuai jadwal kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 485668);
