INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65142575', 65142575, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT WAKIL PRESIDEN', 'Jasa Konsultansi Tenaga Ahli  Pengelolaan  Pengetahuan TP2S Tahun 2026', 'Jasa Konsultansi', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5432631000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 paket', '1) Mengembangkan & memelihara sistem pengelolaan pengetahuan (knowledge management system) utk menyimpan & mengorganisasi pengetahuan terkait dgn pelaksanaan P3S. 2) Mengidentifikasi dan mendokumentasikan praktik baik dlm pelaksanaan P3S di pusat & daerah. 3) Pengelolaan arsip pengetahuan baik berbentuk dokumen, laporan, prosedur, good practices yg mudah di akses bagi publik. 4) Mengidentifikasi kebutuhan pengetahuan dan memastikan bhw pengetahuan yg relevan didistribusikan dgn tepat. 5) Mengorganisir kegiatan utk berbagi pengetahuan antar tim & individu. 6) Melakukan kolaborasi dgn K/L & pemangku kepentingan lainnya utk mendukung pengembangan kapasitas organisasi melalui pengelolaan pengetahuan. 7) Pengembangan & pengelolaan berkala konten pengetahuan berbentuk artikel, panduan, materi lainnya yg terkait ttg P3S. 8) Menjaga profesionalitas, integritas, loyalitas, dan kesetiaan kpd Setwapres. 9) Melaksanakan tugas yg diberikan oleh Setwapres dgn penuh tanggungjawab.', '1) Mempunyai pendidikan S1 dengan pengalaman 7 tahun atau S2 dengan pengalaman 5 tahun di bidang Ilmu Kesehatan Masyarakat, Gizi, Kedokteran, Ilmu Sosial, Komunikasi, Manajemen, dan bidang lain yang relevan. 2) Mempunyai pendidikan tambahan dalam pengelolaan pengetahuan atau sertifikasi terkait akan menjadi nilai tambah. 3) Mempunyai pengalaman kerja lebih dari 5 tahun dalam pengelolaan pengetahuan, manajemen informasi, atau peran serupa. 4) Mempunyai pengalaman dalam pengelolaan database, sistem manajemen konten, metadata, atau pengembangan proses berbagi pengetahuan. 5) Mempunyai pengalaman dan kemampuan komunikasi yang sangat baik, baik tertulis maupun lisan. 6) Memiliki keterampilan dalam menggunakan perangkat lunak pengelolaan pengetahuan dan kolaborasi (misalnya SharePoint, Confluence, atau sistem serupa). 7) Memiliki pemahaman mendalam tentang proses organisasi dan cara berbagi pengetahuan di dalam tim. 8) Memiliki kemampuan untuk menganalisis kebutuhan pengetahuan dan mengidentifikasi area yang memerlukan perbaikan. 9) Memiliki keterampilan dalam merancang dan mengimplementasikan solusi pengelolaan pengetahuan yang efektif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 486495);
