INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62424264', 62424264, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA, STATISTIK DAN PERSANDIAN', 'Tenaga Ahli Pendampingan Implementasi Keterbukaan Informasi Publik', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 68480000, 'December 2025', 'APBD', 1, 1, '8 Bulan', '1. Melakukan Analisis terhadap permohonan informasi yang ditujukan kepada Badan Publik dan Unit Kerja Badan Publik. 2. Melakukan Analisis atas keberatan yang diajukan Pemohon Informasi 3. Melakukan Pendampingan Sidang Sengketa Informasi yang dilaksanakan oleh Komisi Informasi. 4. Melakukan Monitoring dan Evaluasi Penerapan Undang-Undang Keterbukaan Informasi Publik terhadap PPID di lingkup Pemerintah Kabupaten Bandung. 5. Melakukan pendampingan Implementasi Keterbukaan Informasi Publik bagi Unit Kerja Badan Publik 6. Melaksanakan tugas fungsi admin E LAPOR Badan Publik. 7. Melakukan kegiatan lainnya yang berhubungan dengan program dan kegiatan Keterbukaan Informasi publik. 8. Membuat laporan bulanan yang berisikan pelaksanaan kegiatan harian, sebagai pertanggungjawaban atas kinerja yang dilaksanakan.', 'Jasa Tenaga Ahli Spesifikasi : Jasa Tenaga Ahli S1, Pengalaman 5 Tahun; a. Pendidikan minimal Sarjana (S1) Hukum. b. Memahami regulasi keterbukaan informasi publik, khususnya UU Nomor 14 Tahun 2008 dan peraturan pelaksanaannya. c. Mampu melakukan pengelolaan dan dokumentasi informasi publik, baik fisik maupun elektronik, termasuk DIP dan uji konsekuensi. d. Memiliki kemampuan komunikasi dan penyusunan laporan pendampingan serta dokumen teknis. e. Mampu bekerja mandiri maupun dalam tim serta berkoordinasi dengan PPID dan perangkat daerah. f. Berintegritas, beretika profesional, dan tidak pernah terlibat tindakan kriminal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 488002);
